fn prime_num(n: u64) -> bool {
    // Since n >= 2 as per the problem statement,
    // check divisors from 2 up to n-1.
    // If no divisor divides n exactly, n is prime.

    for k in 2..n {
        if n % k == 0 {
            return false;
        }
    }
    true
}